use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let mut fields: Vec<string> = []
        let mut cur = ""
        let mut inq = false
        let mut pending = false
        for c in line.chars() {
            if pending {
                pending = false
                if c == '"' {
                    cur = cur + "\""
                    continue
                }
                inq = false
            }
            if inq {
                if c == '"' {
                    pending = true
                } else {
                    cur = cur + c.to_string()
                }
            } else if c == ',' {
                fields.push(cur)
                cur = ""
            } else if c == '"' {
                inq = true
            } else {
                cur = cur + c.to_string()
            }
        }
        fields.push(cur)
        let n: int = fields.len() as int
        let mut out = "${n}: "
        let mut first = true
        for f in fields {
            if !first {
                out = out + "|"
            }
            first = false
            out = out + "[" + f + "]"
        }
        println(out)
    }
}

